mapper.update:
UPDATE ai_category SET name = #{name}, slug = #{slug}, bg_color = #{bgColor}, accent_color = #{accentColor},
                       sort_order = #{sortOrder}, exposed = #{exposed}, updated_at = now()
WHERE code = #{code}

mapper.select:
SELECT 
FROM ai_post p JOIN ai_category c ON c.code = p.category_code
WHERE p.id = #{id}
